import { cn } from "@/lib/utils";

// Matches http:// and https:// URLs (greedily up to the next whitespace).
// Trailing punctuation is trimmed separately below.
const URL_REGEX = /https?:\/\/[^\s]+/g;

const LINK_CLASSNAME = cn("text-blue-600", "underline", "break-all");

const countChar = (value: string, char: string): number => {
  let count = 0;
  for (let i = 0; i < value.length; i += 1) {
    if (value[i] === char) count += 1;
  }
  return count;
};

// Strips punctuation that commonly sits adjacent to a URL (trailing sentence
// punctuation, and enclosing parentheses/brackets) so the href points at the
// URL only. Parentheses/brackets are only stripped when unbalanced, so URLs
// that legitimately contain them (e.g. wikipedia "(disambiguation)" links)
// stay intact.
const stripTrailingPunctuation = (url: string): string => {
  let result = url;

  while (result.length > 0) {
    const last = result[result.length - 1];

    if (
      last === "." ||
      last === "," ||
      last === ";" ||
      last === ":" ||
      last === "!" ||
      last === "?"
    ) {
      result = result.slice(0, -1);
    } else if (last === ")") {
      if (countChar(result, ")") > countChar(result, "(")) {
        result = result.slice(0, -1);
      } else {
        break;
      }
    } else if (last === "]") {
      if (countChar(result, "]") > countChar(result, "[")) {
        result = result.slice(0, -1);
      } else {
        break;
      }
    } else {
      break;
    }
  }

  return result;
};

const handleAnchorClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
  event.stopPropagation();
};

// Splits a plain string into an ordered list of text fragments and anchor
// elements for any detected http/https URLs. All text is rendered through
// React (never dangerouslySetInnerHTML), so any embedded markup stays inert.
const linkifyString = (text: string): React.ReactNode[] => {
  const nodes: React.ReactNode[] = [];
  const regex = new RegExp(URL_REGEX);

  let lastIndex = 0;
  let key = 0;
  let match: RegExpExecArray | null;

  while ((match = regex.exec(text)) !== null) {
    const raw = match[0];
    const url = stripTrailingPunctuation(raw);
    const start = match.index;

    // Guard against an all-punctuation match collapsing to empty.
    if (url.length === 0) {
      continue;
    }

    if (start > lastIndex) {
      nodes.push(text.slice(lastIndex, start));
    }

    nodes.push(
      <a
        key={`link-${key}`}
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        className={LINK_CLASSNAME}
        onClick={handleAnchorClick}
      >
        {url}
      </a>,
    );
    key += 1;

    // Any stripped trailing punctuation is left in the surrounding text stream.
    lastIndex = start + url.length;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }

  return nodes;
};

const LinkifyText = ({ children }: { children?: React.ReactNode }) => {
  if (children === null || children === undefined) {
    return <></>;
  }

  if (typeof children === "number") {
    return <>{String(children)}</>;
  }

  if (typeof children === "string") {
    // Fast path: no protocol present, render the string verbatim so the
    // container's innerHTML matches the input exactly (no wrapper element).
    if (!children.includes("http") && !children.includes("https")) {
      return <>{children}</>;
    }

    return <>{linkifyString(children)}</>;
  }

  // Any other React node is rendered as-is.
  return <>{children}</>;
};

export default LinkifyText;
